<?php
chdir(dirname(__DIR__));spl_autoload_register(function($c){foreach(['app/Core/','app/Services/']as$p)if(is_file($p.$c.'.php')){require_once$p.$c.'.php';return;}});
$db=DB::getInstance();$parts=$db->query("SELECT m.kode,s.id,s.kode_bagian,s.isi_template FROM master_dokumen_pengadaan_neo m JOIN master_dokumen_pengadaan_bagian_neo s ON s.master_id=m.id AND s.is_deleted=0 WHERE m.kode LIKE 'SW\\_%' AND m.aktif=1 AND m.is_deleted=0")->fetchAll();
foreach($parts as$p){$original=SwakelolaDocumentService::loadBlocks($db,'master_bagian_id',(int)$p['id'])??json_decode($p['isi_template'],true);$expected=SwakelolaTcpdfLayoutService::decorate($p['kode'],$original);$actual=SwakelolaDefaultService::blocks($db,$p['kode'],$p['kode_bagian']);if($expected!=$actual)throw new RuntimeException('Roundtrip berbeda: '.$p['kode']);}
